import { test } from "node:test";
import assert from "node:assert/strict";
import { decodeReading, encodeReading } from "../src/telemetry/wire.ts";
import { exportSince, ingestBatch } from "../src/telemetry/ingest.ts";
import { ReadingStore } from "../src/telemetry/store.ts";

const NOW = new Date("2026-11-19T12:00:00Z");
const nowSeconds = NOW.getTime() / 1000;

const gatewayReading = (secondsAgo: number, extra: Record<string, unknown> = {}) => ({
    device_id: "truck-17",
    recorded_at: nowSeconds - secondsAgo,
    odometer_km: 182_340.5,
    fuel_pct: 61,
    location: { lat: 52.37, lon: 4.89 },
    ...extra,
});

test("a reading from old firmware with an ISO timestamp is decoded", () => {
    const r = decodeReading({ ...gatewayReading(0), recorded_at: "2026-11-19T11:58:00Z" });
    assert.equal(r.recordedAt.toISOString(), "2026-11-19T11:58:00.000Z");
    assert.deepEqual(r.location, { lat: 52.37, lon: 4.89 });
    assert.deepEqual(r.faultCodes, []);
});

test("a gateway reading's Unix-seconds timestamp is decoded to the right instant", () => {
    const r = decodeReading(gatewayReading(90));
    console.log("recorded_at", nowSeconds - 90, "decoded as", r.recordedAt.toISOString());
    assert.equal(r.recordedAt.toISOString(), "2026-11-19T11:58:30.000Z");
});

test("encoding writes snake_case fields and whole Unix seconds", () => {
    const wire = encodeReading({
        deviceId: "truck-3",
        recordedAt: new Date("2026-11-19T11:00:00.750Z"),
        odometerKm: 10,
        fuelPct: 99,
        location: null,
        faultCodes: ["P0420"],
    });
    assert.deepEqual(wire, { device_id: "truck-3", recorded_at: 1795086000, odometer_km: 10, fuel_pct: 99, location: null, fault_codes: ["P0420"] });
});

test("encode then decode gives back the same reading", () => {
    const original = decodeReading({ ...gatewayReading(0), recorded_at: "2026-11-19T10:15:00Z", fault_codes: ["P0300"] });
    const roundTripped = decodeReading(JSON.parse(JSON.stringify(encodeReading(original))));
    assert.deepEqual(roundTripped, original);
});

test("fresh gateway readings are accepted and only genuinely old ones are stale", () => {
    const store = new ReadingStore();
    const body = JSON.stringify([gatewayReading(60), gatewayReading(30), gatewayReading(2 * 86_400)]);
    const result = ingestBatch(body, store, NOW);
    assert.deepEqual(result, { accepted: 2, rejected: [{ index: 2, reason: "stale" }] });
    assert.equal(store.history("truck-17").length, 2);
});

test("malformed readings are rejected with a reason while the rest of the batch goes in", () => {
    const store = new ReadingStore();
    const body = JSON.stringify([
        { ...gatewayReading(0), recorded_at: "2026-11-19T11:59:00Z" },
        { ...gatewayReading(0), fuel_pct: 140 },
        { ...gatewayReading(0), recorded_at: "yesterday-ish" },
        { ...gatewayReading(0), location: "52.37,4.89" },
    ]);
    const result = ingestBatch(body, store, NOW);
    assert.equal(result.accepted, 1);
    assert.deepEqual(result.rejected.map((r) => r.index), [1, 2, 3]);
    assert.match(result.rejected[0].reason, /fuel_pct/);
});

test("the dispatcher map and the partner export see trucks reporting through the gateway", () => {
    const store = new ReadingStore();
    ingestBatch(JSON.stringify([gatewayReading(600), gatewayReading(120, { location: { lat: 52.4, lon: 4.9 } })]), store, NOW);
    const latest = store.latestPositions().get("truck-17");
    assert.deepEqual(latest, { lat: 52.4, lon: 4.9, at: new Date("2026-11-19T11:58:00Z") });

    const exported = JSON.parse(exportSince(store, ["truck-17"], new Date("2026-11-19T11:55:00Z")));
    assert.deepEqual(exported.map((w: { recorded_at: number }) => w.recorded_at), [nowSeconds - 120]);
});
